export default {
  mixins: [loadingMixin],
  data: () => ({ q: '' }),
  watch: { q: 'search' },
  methods: { search() {} },
}

// Composition: one feature, one function
export function useSearch() {
  const q = ref('')
  const { loading, run } = useLoading()
  watch(q, run)
  return { q, loading }
}

