export function useWindowWidth() {
  const w = ref(0)
  function onResize() { w.value = window.innerWidth }
  window.addEventListener('resize', onResize) // ❌ crashes SSR
  onScopeDispose(() => window.removeEventListener('resize', onResize))
  return w
}

